#!/usr/bin/env python3\nimport sys\nimport os\nsys.path.append(os.path.dirname(os.path.abspath(__file__)))\n\nfrom database import sync_results_collection\nfrom scraper import ZomatoScraper\nimport logging\n\nlogging.basicConfig(level=logging.INFO)\n\ndef test_simple_scraper():\n    job_id = \"test_simple\"\n    scraper = ZomatoScraper(job_id, num_workers=1)\n    \n    # Test single restaurant\n    success, result = scraper.scrape_restaurant(\"20752747\")\n    \n    if success:\n        print(f\"✅ Success!\")\n        print(f\"ID: {result.res_id}\")\n        print(f\"Name: {result.name}\")\n        print(f\"URL: {result.url}\")\n        print(f\"Address: {result.address}\")\n        print(f\"Cost: {result.cost}\")\n    else:\n        print(\"❌ Failed\")\n    \n    # Clean up test data\n    sync_results_collection.delete_many({\"job_id\": job_id})\n\nif __name__ == \"__main__\":\n    test_simple_scraper()\n